        #slider {
            position: relative;
            max-width: 100%;
            height: auto;
            min-height:340px;
            margin: 0 auto;
            overflow: hidden;
        }

        .slide {
            position: absolute;
            width: 100%;
            height: 100%;
            top: 0;
            left: 0;
            z-index: 1;
            transition: transform .5s ease-in-out;
            padding:0px 120px;
        }

        .current-slide {
            transform: translateX(0);
            z-index: 2;
        }
        .previous-slide {
            transform: translateX(-100%);
            z-index: 1;
        }
        .next-slide {
            transform: translateX(100%);
            z-index: 1;
        }
        .active {
            z-index: 2;
        }
        
        .active .dot{
            background-color:grey;
        }

